        ["UPDATE GESPERRT · Aktuellen Verkauf zuerst kassieren, PARKEN oder mit C leeren."] = "GÜNCELLEME KİLİTLİ · önce mevcut satışı tahsil edin, BEKLETİN veya C ile temizleyin.",
