        // Einstellungen · Navigation und Berichte/E-Mail
        ["Kasse & Bedienung"] = "Kasa & kullanım",
        ["Firma & Bon"] = "Firma & fiş",
        ["Artikel & Steuern"] = "Ürünler & vergiler",
