        ["Software & Update"] = "Yazılım & güncelleme",
        ["Erweitert / Techniker 🔒"] = "Gelişmiş / Teknik servis 🔒",
        ["Erweitert / Techniker"] = "Gelişmiş / Teknik servis",
        ["Alle Standardberichte können als PDF gespeichert werden. Optional verschickt TOR POS einmal pro Monat automatisch ein PDF-Paket per E-Mail."] = "Tüm standart raporlar PDF olarak kaydedilebilir. İsteğe bağlı olarak TOR POS ayda bir kez otomatik PDF paketini e-posta ile gönderir.",
        ["Monatlicher PDF-Versand"] = "Aylık PDF gönderimi",
        ["Monatliche Berichte automatisch per E-Mail senden"] = "Aylık raporları otomatik e-posta ile gönder",
        ["Empfänger-E-Mail"] = "Alıcı e-posta",
        ["Diese Adresse erhält das monatliche PDF-Paket."] = "Aylık PDF paketi bu adrese gönderilir.",
        ["Versandtag"] = "Gönderim günü",
        ["1–28 · Standard 1. Versendet den abgeschlossenen Vormonat."] = "1–28 · Varsayılan 1. Tamamlanan önceki ayı gönderir.",
        ["Versandzeit"] = "Gönderim saati",
        ["HH:mm · Standard 00:15. Bei ausgeschaltetem TOR POS wird der verpasste Versand nach dem nächsten Start nachgeholt."] = "SS:dd · Varsayılan 00:15. TOR POS kapalıysa kaçırılan gönderim bir sonraki açılıştan sonra yapılır.",
        ["Sicherheitsregel"] = "Güvenlik kuralı",
        ["Der E-Mail-Versand erzeugt KEINEN Z-Bericht, keinen Tagesabschluss und keinen Kassenabschluss."] = "E-posta gönderimi yeni bir Z-Bericht, gün sonu veya kasa kapanışı oluşturmaz.",
        ["TOR Mail · empfohlen · keine Google-/SMTP-Einrichtung"] = "TOR Mail · önerilen · Google/SMTP kurulumu gerekmez",
        ["Der Kunde trägt nur die Empfänger-E-Mail ein. Der Absender und die SMTP-Zugangsdaten liegen ausschließlich auf dem TOR POS Cloud-Server und werden niemals auf der Kasse gespeichert."] = "Müşteri yalnızca alıcı e-posta adresini girer. Gönderen ve SMTP erişim bilgileri sadece TOR POS Cloud sunucusunda bulunur ve kasada hiçbir zaman saklanmaz.",
        ["TOR MAIL ALS VERSANDWEG VERWENDEN"] = "TOR MAIL'İ GÖNDERİM YOLU OLARAK KULLAN",
        ["TOR MAIL TEST-E-MAIL SENDEN"] = "TOR MAIL TEST E-POSTASI GÖNDER",
        ["Voraussetzung: TOR POS Cloud muss unter Geräte eingerichtet sein. Der zentrale Mail-Absender wird einmalig von TOR auf dem Cloud-Server konfiguriert; der Kunde benötigt dafür kein Google-Konto, App-Passwort oder SMTP-Wissen."] = "Ön koşul: TOR POS Cloud, Cihazlar altında kurulmuş olmalıdır. Merkezi e-posta göndereni TOR tarafından Cloud sunucusunda bir kez yapılandırılır; müşterinin Google hesabına, uygulama parolasına veya SMTP bilgisine ihtiyacı yoktur.",
        ["Google-Konto / Gmail API (Alternative)"] = "Google hesabı / Gmail API (alternatif)",
        ["Kein Gmail-Passwort und kein App-Passwort in TOR POS: MIT GOOGLE ANMELDEN erzeugt einen einmaligen QR-Code. Der Inhaber scannt ihn mit dem Handy und bestätigt die Berechtigung direkt bei Google."] = "TOR POS içinde Gmail parolası veya uygulama parolası yoktur: GOOGLE İLE GİRİŞ tek kullanımlık QR kodu oluşturur. İşletme sahibi telefonuyla tarar ve yetkiyi doğrudan Google'da onaylar.",
        ["MIT GOOGLE ANMELDEN (QR)"] = "GOOGLE İLE GİRİŞ (QR)",
        ["GOOGLE TEST-E-MAIL SENDEN"] = "GOOGLE TEST E-POSTASI GÖNDER",
        ["GOOGLE-VERBINDUNG TRENNEN"] = "GOOGLE BAĞLANTISINI KES",
        ["Voraussetzung für QR-Anmeldung: TOR POS Cloud muss unter Geräte eingerichtet sein und der Cloud-Server benötigt eine freigegebene Google-OAuth-Konfiguration. Die Monatsberichte selbst gehen direkt von diesem PC an die Gmail API; die PDF-Dateien werden nicht über TOR POS Cloud geleitet."] = "QR ile giriş için TOR POS Cloud, Cihazlar altında kurulmuş olmalı ve Cloud sunucusunda onaylı Google OAuth yapılandırması bulunmalıdır. Aylık raporlar bu bilgisayardan doğrudan Gmail API'ye gider; PDF dosyaları TOR POS Cloud üzerinden aktarılmaz.",
        ["Eigener E-Mail-Ausgang / SMTP (Alternative)"] = "Kendi e-posta çıkışı / SMTP (alternatif)",
        ["Absender-E-Mail"] = "Gönderen e-posta",
        ["Für Gmail: smtp.gmail.com"] = "Gmail için: smtp.gmail.com",
