        ["SMTP App-Passwort"] = "SMTP uygulama parolası",
        ["Leer lassen, um ein bereits gespeichertes App-Passwort zu behalten. Google-App-Passwort-Leerzeichen werden automatisch entfernt."] = "Daha önce kaydedilmiş uygulama parolasını korumak için boş bırakın. Google uygulama parolasındaki boşluklar otomatik kaldırılır.",
        ["GMAIL-STANDARD ÜBERNEHMEN"] = "GMAIL VARSAYILANINI UYGULA",
