        ["Geschäftsdaten werden zentral gepflegt und später für Bon, Berichte und fiskale Dokumente verwendet."] = "İşletme bilgileri merkezi olarak tutulur ve fiş, raporlar ve fiskal belgelerde kullanılır.",
