        ["Straße"] = "Cadde",
        ["PLZ"] = "Posta kodu",
        ["Ort"] = "Şehir",
        ["Telefon"] = "Telefon",
        ["E-Mail"] = "E-posta",
        ["Steuernummer"] = "Vergi numarası",
        ["USt-IdNr."] = "KDV kimlik no.",
        ["Verwendung"] = "Kullanım",
        ["Firmendaten auf dem Bon verwenden"] = "Firma bilgilerini fişte kullan",
        ["Firmendaten auf Berichten verwenden"] = "Firma bilgilerini raporlarda kullan",
        ["Bedienfunktionen"] = "Kullanım işlevleri",
        ["Nur Funktionen einschalten, die der Betrieb tatsächlich benutzt."] = "Yalnızca işletmenin gerçekten kullandığı işlevleri açın.",
        ["Verkauf"] = "Satış",
        ["Sonstige Artikel / freie Preiseingabe anzeigen"] = "Diğer ürün / serbest fiyat girişini göster",
        ["Pfand / Leergut anzeigen"] = "Depozito / boş ambalajı göster",
        ["Gastronomie · Extras"] = "Gastronomi · Ekstralar",
        ["Verwaltung direkt im Artikel / unter STAMMDATEN → EXTRAS"] = "Yönetim doğrudan ürün içinde / ANA VERİLER → EKSTRALAR altında",
        ["Bei kritischem Warenbestand warnen"] = "Kritik stokta uyar",
        ["Mindestbestand"] = "Minimum stok",
        ["Warnschwelle, z.B. 5 Stück."] = "Uyarı eşiği, örn. 5 adet.",
        ["Abholnummer / Bestellablauf"] = "Teslim numarası / sipariş akışı",
        ["Schnellauswahl"] = "Hızlı seçim",
        ["OFF = aus · SALE = Nummer beim Kassieren · ORDER = Nummer sofort bei Bestellannahme"] = "OFF = kapalı · SALE = ödeme sırasında numara · ORDER = sipariş alınırken hemen numara",
        ["Empfohlen für Gastronomie mit Bestell-/Abholablauf (z. B. Döner, Imbiss, Café, Restaurant): ORDER. Dann erscheint in der Kasse BESTELLUNG ANNEHMEN · F3 · ABHOLNR.; der eigentliche Bon entsteht erst später bei BAR/KARTE."] = "Sipariş/teslim akışı olan gastronomi için önerilir (örn. döner, büfe, kafe, restoran): ORDER. Kasada BESTELLUNG ANNEHMEN · F3 · ABHOLNR. görünür; gerçek fiş daha sonra BAR/KARTE ile oluşur.",
        ["Bei Bestellannahme eine Abholnummer vergeben"] = "Sipariş alınırken teslim numarası ver",
        ["Bei ORDER einen Abholschein für den Kunden drucken"] = "ORDER sırasında müşteri için teslim fişi yazdır",
        ["Training"] = "Eğitim",
        ["ORDER kann jetzt auch mit dem TRAINING-Benutzer getestet werden. Trainingsbestellungen und Trainings-Abholnummern bleiben getrennt von echten offenen Bestellungen."] = "ORDER artık TRAINING kullanıcısıyla da test edilebilir. Eğitim siparişleri ve teslim numaraları gerçek açık siparişlerden ayrı kalır.",
        ["Wichtig"] = "Önemli",
        ["Abholnummer ist nur eine Betriebs-/Wartenummer und ersetzt niemals die Bonnummer."] = "Teslim numarası yalnızca işletme/bekleme numarasıdır ve hiçbir zaman fiş numarasının yerine geçmez.",
        // The TSE outage list. The recorded reason itself is never translated -
        // it is the documented cause of a fiscal outage and reaches a Pruefer
        // exactly as the till wrote it.
        ["TSE-Ausfälle"] = "TSE arızaları",
        ["Jeder Ausfall wird mit Beginn, Ende und Grund protokolliert und kann nicht gelöscht werden. Dieselben Daten gehen in den DSFinV-K-Export."] =
            "Her arıza başlangıcı, bitişi ve sebebiyle kaydedilir ve silinemez. Aynı veriler DSFinV-K dışa aktarımına da gider.",
        ["AUSFALLLISTE AKTUALISIEREN"] = "ARIZA LİSTESİNİ YENİLE",
        ["Ausfallliste wird gelesen ..."] = "Arıza listesi okunuyor ...",
        ["Kein TSE-Ausfall protokolliert."] = "Kayıtlı TSE arızası yok.",
        ["Ausfallliste konnte nicht gelesen werden."] = "Arıza listesi okunamadı.",
        // The TSE clock. "TimeAdmin" is the name Swissbit gives that PIN and
        // stays as it is, like TSE itself.
        ["TSE-Uhrzeit"] = "TSE saati",
        ["Warum"] = "Neden",
        ["Eine TSE signiert nicht mehr, sobald ihre eigene Uhr ungültig ist. Das passiert nach längerer Lagerung oder wenn die Kasse lange ausgeschaltet war."] =
            "Kendi saati geçersiz hale geldiğinde TSE artık imzalamaz. Bu, uzun depolamadan sonra veya kasa uzun süre kapalı kaldığında olur.",
        ["TimeAdmin-PIN ist auf dieser Kasse gespeichert"] = "TimeAdmin-PIN bu kasada kayıtlı",
        ["Nur die TimeAdmin-PIN. Sie kann ausschließlich die Uhr stellen - keine PIN ändern, keinen Client registrieren, die TSE nicht außer Betrieb setzen. Admin-PIN, PUK und Credential-Seed werden nirgends gespeichert."] =
            "Yalnızca TimeAdmin-PIN. Bu PIN sadece saati ayarlayabilir - PIN değiştiremez, client kaydedemez, TSE'yi hizmet dışı bırakamaz. Admin-PIN, PUK ve Credential-Seed hiçbir yere kaydedilmez.",
        ["PIN SPEICHERN"] = "PIN'İ KAYDET",
        ["GESPEICHERTE PIN LÖSCHEN"] = "KAYITLI PIN'İ SİL",
        ["Keine TimeAdmin-PIN eingegeben."] = "TimeAdmin-PIN girilmedi.",
        ["TimeAdmin-PIN gespeichert. Die TSE-Uhr wird jetzt automatisch nachgeführt."] =
            "TimeAdmin-PIN kaydedildi. TSE saati artık otomatik olarak güncellenecek.",
        ["Gespeicherte TimeAdmin-PIN gelöscht."] = "Kayıtlı TimeAdmin-PIN silindi.",
        // Cloud TSE. "TSE", "Cloud-TSE", "Queue", "API" and the vendor names
        // stay as they are: a technician and the vendor's contract use them.
        ["Art der TSE"] = "TSE türü",
        ["Auswahl"] = "Seçim",
        ["SWISSBIT_USB = TSE steckt als USB-Stick in dieser Kasse. CLOUD = zertifizierte TSE eines Anbieters über HTTPS. Die Umstellung wirkt erst nach einem Neustart."] =
            "SWISSBIT_USB = TSE bu kasaya USB bellek olarak takılıdır. CLOUD = bir sağlayıcının HTTPS üzerinden sunulan sertifikalı TSE'si. Değişiklik ancak yeniden başlatmadan sonra etkili olur.",
        ["Ein unbekannter Wert fällt auf SWISSBIT_USB zurück. Eine Kasse wird nie stillschweigend auf ein anderes Fiskalgerät umgestellt."] =
            "Bilinmeyen bir değer SWISSBIT_USB'ye düşer. Bir kasa asla sessizce başka bir fiskal cihaza geçirilmez.",
        ["Cloud-TSE"] = "Cloud-TSE",
        ["Freigabe"] = "Onay",
        ["Cloud-TSE ist für diesen Anbieter freigegeben."] = "Cloud-TSE bu sağlayıcı için onaylıdır.",
        ["Cloud-TSE ist für diesen Anbieter NICHT freigegeben. Einstellungen können erfasst und der Endpunkt geprüft werden; es wird nichts signiert."] =
            "Cloud-TSE bu sağlayıcı için ONAYLI DEĞİLDİR. Ayarlar girilebilir ve uç nokta test edilebilir; hiçbir şey imzalanmaz.",
        ["Mandant / Queue"] = "Müşteri hesabı / Queue",
        ["Mandant und Queue gehören zusammen und müssen zu dieser Kasse passen. Die gefährlichste Verwechslung bei einer Cloud-TSE ist eine Kasse, die in die Queue eines fremden Mandanten signiert: die Belege sehen gültig aus und gehören in fremde Bücher."] =
            "Hesap ve Queue birbirine aittir ve bu kasayla eşleşmelidir. Cloud-TSE'de en tehlikeli karışıklık, başka bir hesabın Queue'suna imza atan bir kasadır: fişler geçerli görünür ve başkasının defterine yazılır.",
        ["Anbieter"] = "Sağlayıcı",
        ["Endpunkt"] = "Uç nokta",
        ["Mandant"] = "Hesap",
        ["Queue"] = "Queue",
        ["API-Schlüssel"] = "API anahtarı",
        ["Der zertifizierte Cloud-TSE-Anbieter, mit dem ein Vertrag besteht. Jeder Anbieter wird einzeln freigegeben: die Freigabe eines Anbieters öffnet keinen anderen."] =
            "Sözleşme yapılan sertifikalı Cloud-TSE sağlayıcısı. Her sağlayıcı ayrı ayrı onaylanır: birinin onayı diğerini açmaz.",
        ["Vollständige HTTPS-Adresse. Andere Protokolle werden abgelehnt."] = "Tam HTTPS adresi. Diğer protokoller reddedilir.",
        ["Muss die Kassen-Seriennummer sein - dieselbe Nummer wie auf dem Bon und im DSFinV-K-Export."] =
            "Kasa seri numarası olmalıdır - fişteki ve DSFinV-K dışa aktarımındaki numaranın aynısı.",
        ["Wird DPAPI-geschützt gespeichert und nie im Klartext abgelegt oder protokolliert."] =
            "DPAPI ile korunarak saklanır; asla düz metin olarak kaydedilmez veya loglanmaz.",
        ["CLOUD-TSE VERBINDUNG PRÜFEN"] = "CLOUD-TSE BAĞLANTISINI TEST ET",
        ["Cloud-TSE Endpunkt wird geprüft ..."] = "Cloud-TSE uç noktası kontrol ediliyor ...",
        ["läuft noch"] = "hâlâ sürüyor",
        ["Tag"] = "gün",
        ["Tage"] = "gün",
        ["Std."] = "sa.",
        ["Min."] = "dk.",
        ["Tagesabschluss"] = "Gün sonu",
        ["Z-Bericht automatisch drucken"] = "Z-Bericht'i otomatik yazdır",
        ["Z-Abschluss bleibt bei offenen geparkten Bons gesperrt."] = "Açık bekletilmiş fişler varken Z-Abschluss kilitli kalır.",
        ["Zahlarten"] = "Ödeme türleri",
        ["Zahlarten werden separat konfiguriert. Die Karten-Zahlart wird später direkt mit ZVT verbunden."] = "Ödeme türleri ayrı yapılandırılır. Kart ödeme türü daha sonra doğrudan ZVT'ye bağlanır.",
        ["Aktive Zahlarten"] = "Aktif ödeme türleri",
        ["Bar aktiv"] = "Nakit aktif",
        ["Karte aktiv"] = "Kart aktif",
        ["Auf Rechnung aktiv"] = "Fatura hesabı aktif",
        ["Bezeichnung Bar"] = "Nakit etiketi",
        ["Bezeichnung Karte"] = "Kart etiketi",
        ["Bezeichnung Rechnung"] = "Fatura hesabı etiketi",
        ["Schnellkassieren · F5"] = "Hızlı ödeme · F5",
        ["Standard-Zahlart"] = "Varsayılan ödeme türü",
        ["AUS = F5 öffnet die Zahlart-Auswahl. BAR/KARTE = F5 startet die gewählte Zahlart direkt."] = "KAPALI = F5 ödeme türü seçimini açar. BAR/KARTE = F5 seçilen ödeme türünü doğrudan başlatır.",
        ["Bei F5 + BAR sofort als PASSEND kassieren (kein Rückgeld-Dialog)"] = "F5 + BAR ile hemen TAM olarak tahsil et (para üstü penceresi yok)",
        ["F1 BAR bleibt immer die normale Barzahlung mit Gegeben/Rückgeld. F2 KARTE bleibt direkte Kartenzahlung. Die gespeicherte Zahlart ist auch beim Schnellkassieren immer eindeutig BAR oder KARTE."] = "F1 BAR her zaman verilen/para üstü olan normal nakit ödemedir. F2 KARTE doğrudan kart ödemesidir. Hızlı ödemede de kayıtlı ödeme türü her zaman açıkça BAR veya KARTE olarak kalır.",
        ["Angebote / Rabatte"] = "Teklifler / indirimler",
        ["Manuellen Rabatt zusätzlich zu einem aktiven Angebot erlauben"] = "Aktif teklife ek olarak manuel indirime izin ver",
        ["Standard"] = "Varsayılan",
        ["AUS empfohlen: Angebot und manueller Rabatt werden nicht automatisch gestapelt. Pfand wird niemals durch Angebot rabattiert."] = "KAPALI önerilir: teklif ve manuel indirim otomatik üst üste uygulanmaz. Depozitoya hiçbir zaman teklif indirimi uygulanmaz.",
        ["Kartenzahlung"] = "Kart ödemesi",
        ["Bei aktivierter Terminalintegration wird ein Kartenverkauf erst nach erfolgreicher Terminalbestätigung als Verkauf gespeichert."] = "Terminal entegrasyonu etkinse kartlı satış ancak terminal başarıyla onayladıktan sonra satış olarak kaydedilir.",

        // Einstellungen · Geräte, Cloud, Backup und Personal
        ["Drucker & Geräte"] = "Yazıcılar ve cihazlar",
        ["Windows-Drucker auswählen, testen und unten SPEICHERN drücken. Das Kartenterminal wird über den Marken-Assistenten verbunden."] = "Windows yazıcısını seçin, test edin ve aşağıda KAYDET'e basın. Kart terminali marka sihirbazı üzerinden bağlanır.",
        ["WAAGEN-EINSTELLUNGEN · MANUELL / COM / LAN / BARCODE"] = "TERAZİ AYARLARI · MANUEL / COM / LAN / BARKOD",
        ["Gewichtsverkauf"] = "Tartılı satış",
        ["Gewichtsartikel werden intern in kg geführt. Eine separate Waage ohne Kassenanschluss ist vollständig nutzbar: Gewicht ablesen und beim Verkauf in Gramm oder Kilogramm eingeben. COM/LAN/Waagenbarcode können zusätzlich vorbereitet werden."] = "Tartılı ürünler sistem içinde kg olarak tutulur. Kasaya bağlı olmayan ayrı bir terazi tamamen kullanılabilir: ağırlığı okuyup satışta gram veya kilogram olarak girin. COM/LAN/terazi barkodu ayrıca hazırlanabilir.",
        ["DRUCKER-ZENTRALE · EPSON / STAR AUTOMATISCH ERKENNEN"] = "YAZICI MERKEZİ · EPSON / STAR OTOMATİK TANIMA",
        ["Automatische Druckererkennung"] = "Otomatik yazıcı algılama",
        ["TOR liest die in Windows installierten Drucker, Treiber und Ports und erkennt verbreitete Epson-TM- sowie Star-mC/TSP-Bondrucker. Ein konkretes Modell wird nur bei eindeutiger Kennung übernommen; bei unklarem Modell muss der Benutzer die Auswahl bestätigen."] = "TOR, Windows'ta kurulu yazıcıları, sürücüleri ve portları okur ve yaygın Epson-TM ile Star-mC/TSP fiş yazıcılarını algılar. Belirli model yalnızca açıkça tanındığında kabul edilir; belirsiz modelde kullanıcı seçimi onaylamalıdır.",
        ["KARTENTERMINAL VERBINDEN · MARKE AUSWÄHLEN"] = "KART TERMİNALİ BAĞLA · MARKA SEÇ",
        ["Terminal-Assistent"] = "Terminal sihirbazı",
        ["Bondrucker"] = "Fiş yazıcısı",
        ["Küchendrucker / 2. Drucker"] = "Mutfak yazıcısı / 2. yazıcı",
        ["Bestellung automatisch an Küchendrucker senden"] = "Siparişi otomatik olarak mutfak yazıcısına gönder",
        ["Küchenbon"] = "Mutfak fişi",
        ["Küchenbons bleiben immer auf Deutsch und sind klar als KEIN STEUERBELEG gekennzeichnet. Im ORDER-Modus wird die Küche direkt bei Bestellannahme informiert; OFF/SALE drucken erst beim Kassieren."] = "Mutfak fişleri her zaman Almanca kalır ve açıkça KEIN STEUERBELEG olarak işaretlenir. ORDER modunda mutfak sipariş alınırken bilgilendirilir; OFF/SALE ancak tahsilatta yazdırır.",
        ["Küchenrouting nach Station"] = "İstasyona göre mutfak yönlendirmesi",
        ["Küchendrucker · Grill"] = "Mutfak yazıcısı · Izgara",
        ["Küchendrucker · Fritteuse"] = "Mutfak yazıcısı · Fritöz",
        ["Küchendrucker · Getränke"] = "Mutfak yazıcısı · İçecekler",
        ["A4-Drucker"] = "A4 yazıcı",
        ["GERÄTESTATUS AKTUALISIEREN"] = "CİHAZ DURUMUNU GÜNCELLE",
        ["Terminal & TSE"] = "Terminal & TSE",
        ["Kassenlade verwenden"] = "Kasa çekmecesini kullan",
        ["Kassenschublade · Verbindungstest"] = "Kasa çekmecesi · bağlantı testi",
        ["Noch nicht getestet. Der Test erzeugt keinen Verkauf und keinen Bon."] = "Henüz test edilmedi. Test satış veya fiş oluşturmaz.",
        ["KASSENSCHUBLADE TESTEN"] = "KASA ÇEKMECESİNİ TEST ET",
        ["Der Test sendet genau einen ESC-p/StarPRNT-Impuls über den ausgewählten Bondrucker. Kein Verkauf, keine TSE-Transaktion, kein Bon."] = "Test, seçilen fiş yazıcısı üzerinden tam bir ESC-p/StarPRNT darbesi gönderir. Satış yok, TSE işlemi yok, fiş yok.",
        ["Kundendisplay verwenden"] = "Müşteri ekranını kullan",
        ["Kundendisplay · eigener Bildschirm"] = "Müşteri ekranı · ayrı ekran",
        ["Bildschirm"] = "Ekran",
        ["0 = automatisch einen zweiten Bildschirm (nie den Kassenbildschirm); 1 = Windows-Hauptbildschirm, 2–4 = weitere Bildschirme von links nach rechts."] = "0 = otomatik olarak ikinci bir ekran (asla kasa ekranı değil); 1 = Windows ana ekranı, 2–4 = diğer ekranlar soldan sağa.",
