        ["Nur Bestellungen"] = "Yalnız siparişler",
        ["TOR POS Cloud · Synchronisierung"] = "TOR POS Cloud · senkronizasyon",
        ["Verbindung und Bestand direkt mit dem Kundenportal prüfen. Testbons werden nicht als Umsatz übertragen."] = "Bağlantı ve stoğu doğrudan müşteri portalıyla kontrol edin. Test fişleri ciro olarak aktarılmaz.",
        ["Leer lassen: gespeichertes Token behalten"] = "Boş bırak: kayıtlı token kalsın",
