        ["Das Ziel bleibt für wartende Daten fest zugeordnet."] = "Hedef, bekleyen veriler için sabit atanmış kalır.",
        ["Gerätetoken"] = "Cihaz tokenı",
        ["Verschlüsselt für dieses Windows-Benutzerkonto gespeichert. Nicht im Chat teilen."] = "Bu Windows kullanıcı hesabı için şifreli saklanır. Sohbette paylaşmayın.",
        ["CLOUD SPEICHERN"] = "CLOUD'U KAYDET",
        ["VERBINDUNG PRÜFEN"] = "BAĞLANTIYI KONTROL ET",
        ["JETZT VOLLSTÄNDIG ABGLEICHEN"] = "ŞİMDİ TAM SENKRONİZE ET",
