        ["Noch nicht geprüft. Auswahl und Test bestätigen keinen Papierausdruck."] = "Henüz kontrol edilmedi. Seçim ve test kâğıt çıktıyı doğrulamaz.",
        ["Barcode-Scanner"] = "Barkod tarayıcı",
