        ["Menge je Position eingeben, die zurückgenommen werden soll. Bereits zurückgenommene Mengen werden serverseitig erneut geprüft."] =
            "Her kalem için iade edilecek miktarı girin. Daha önce iade edilmiş miktarlar sunucu tarafında yeniden kontrol edilir.",
        ["Bemerkung (optional), z. B. Zählfehler Wechselgeld"] = "Not (isteğe bağlı), ör. para üstü sayım hatası",
