        ["Noch nicht geprüft."] = "Henüz kontrol edilmedi.",
        ["SYSTEMSTATUS / DIAGNOSE"] = "SİSTEM DURUMU / TANILAMA",
        ["Geräte werden nur auf Anforderung geprüft. Jeder externe Test ist zeitlich begrenzt und darf die Kassenoberfläche nicht lange blockieren."] =
            "Cihazlar yalnızca istendiğinde kontrol edilir. Her dış test süre sınırlıdır ve kasa ekranını uzun süre bloke edemez.",
        ["z. B. 20260914-153000-AB12"] = "ör. 20260914-153000-AB12",
