        ["Admin-Passwort"] = "Yönetici şifresi",
        ["Terminalbeleg / Trace / Prüfnachweis und Begründung"] = "Terminal belgesi / trace / kanıt ve gerekçe",
        ["Zuerst Terminal / Netzbetreiber prüfen. Diese Auswahl sendet weder Zahlung noch Storno an das Terminal."] =
            "Önce terminali / ağ işletmecisini kontrol edin. Bu seçim terminale ne ödeme ne de iptal gönderir.",
        ["Aktuelles Passwort"] = "Geçerli şifre",
        ["Neues Passwort (mindestens 4 Zeichen)"] = "Yeni şifre (en az 4 karakter)",
        ["Neues Passwort wiederholen"] = "Yeni şifreyi tekrarlayın",
        ["Neue PIN (4 Ziffern)"] = "Yeni PIN (4 rakam)",
        ["Vor dem ersten Kassenstart müssen Standard-Zugangsdaten geändert werden."] =
            "İlk kasa açılışından önce varsayılan erişim bilgileri değiştirilmelidir.",
        ["ZAHLUNG PRÜFEN"] = "ÖDEMEYİ KONTROL ET",
        ["ADMIN-ZUGANG EINRICHTEN"] = "YÖNETİCİ ERİŞİMİNİ KUR",
        ["1 · GERÄTELISTE LADEN"] = "1 · CİHAZ LİSTESİNİ YÜKLE",
        ["2 · GERÄTESTATUS PRÜFEN"] = "2 · CİHAZ DURUMUNU KONTROL ET",
        ["3 · 1,00 € TEST AN SOLO SENDEN"] = "3 · SOLO'YA 1,00 € TEST GÖNDER",
        ["4 · TEST ABBRECHEN"] = "4 · TESTİ İPTAL ET",
        ["SOLO MIT DIESEM KONTO KOPPELN"] = "SOLO'YU BU HESAPLA EŞLEŞTİR",
        ["Händlercode (Merchant Code)"] = "Bayi kodu (Merchant Code)",
        ["SumUp API-Key"] = "SumUp API anahtarı",
        ["Werbung im Leerlauf anzeigen"] = "Boştayken reklam göster",
        ["Werbeinhalt"] = "Reklam içeriği",
        ["BEIDE = eigene Werbebilder und Artikel mit Bild · BILDER = nur eigene Werbebilder · ARTIKEL = Artikel mit Bild, Preis und aktivem Angebot."] = "BEIDE = kendi reklam görselleri ve resimli ürünler · BILDER = yalnızca kendi reklam görselleri · ARTIKEL = resmi, fiyatı ve aktif kampanyası olan ürünler.",
        ["Wechsel alle (Sek.)"] = "Değişim aralığı (sn)",
        ["Sobald ein Artikel gescannt wird, zeigt das Kundendisplay sofort den Warenkorb."] = "Bir ürün okutulduğu anda müşteri ekranı hemen sepeti gösterir.",
        ["WERBEBILDER HINZUFÜGEN"] = "REKLAM GÖRSELİ EKLE",
        ["WERBEBILDER-ORDNER ÖFFNEN"] = "REKLAM KLASÖRÜNÜ AÇ",
        ["Werbung im Leerlauf"] = "Boştayken reklam",
        ["Ohne Kunden wechselt das Kundendisplay zwischen den eigenen Werbebildern (JPG, PNG, BMP, WEBP; Reihenfolge nach Dateiname) und Artikeln mit Bild. Artikelkarten zeigen den aktuellen Verkaufspreis und ein aktives Angebot genau so, wie die Kasse sie berechnet. Kein Einfluss auf Bon, TSE oder Kassiervorgang."] = "Müşteri yokken müşteri ekranı kendi reklam görselleriniz (JPG, PNG, BMP, WEBP; sıra dosya adına göre) ile resimli ürünler arasında geçiş yapar. Ürün kartları güncel satış fiyatını ve aktif kampanyayı kasanın hesapladığı şekilde gösterir. Fişi, TSE'yi ve ödeme işlemini etkilemez.",
        ["Nicht übernommen"] = "Alınmadı",
        ["Werbebilder konnten nicht übernommen werden"] = "Reklam görselleri eklenemedi",
        ["Ordner konnte nicht geöffnet werden"] = "Klasör açılamadı",
        ["Noch keine eigenen Werbebilder. Artikel mit Bild werden trotzdem gezeigt, wenn der Inhalt BEIDE oder ARTIKEL ist."] = "Henüz kendi reklam görseliniz yok. İçerik BEIDE veya ARTIKEL ise resimli ürünler yine de gösterilir.",
        ["eigene Werbebilder"] = "kendi reklam görseli",
        ["Werbebilder gespeichert"] = "Reklam görselleri kaydedildi",
        ["Werbebilder-Ordner konnte nicht gelesen werden"] = "Reklam klasörü okunamadı",
        ["Werbe-TV im Netzwerk verwenden"] = "Ağdaki reklam TV'sini kullan",
        ["Werbe-TV · Smart-TV im WLAN"] = "Reklam TV · Wi-Fi'daki Smart TV",
        ["Der TV prüft jede Minute, ob sich Bilder oder Preise geändert haben."] = "TV, görsellerin veya fiyatların değişip değişmediğini her dakika kontrol eder.",
        ["TV-Port"] = "TV portu",
        ["Nur ändern, wenn ein anderes Programm diesen Port belegt."] = "Yalnızca başka bir program bu portu kullanıyorsa değiştirin.",
        ["NEUE TV-ADRESSE ERZEUGEN"] = "YENİ TV ADRESİ OLUŞTUR",
        ["So kommt die Werbung auf den TV"] = "Reklamlar TV'ye nasıl gelir",
        ["Kasse und TV im selben WLAN/Netzwerk. Am TV den Internet-Browser öffnen (Samsung: Internet, LG: Webbrowser, Android TV: z. B. ein Kiosk-Browser) und die Adresse oben eingeben. Die Werbebilder sind dieselben wie beim Kundendisplay; Inhalt und Wechselzeit werden hier getrennt eingestellt. Beim ersten Start fragt Windows eventuell nach der Firewall: Zugriff in privaten Netzwerken erlauben. Die Seite ist nur im eigenen Netzwerk erreichbar und hat keinen Einfluss auf Bon, TSE oder Kassiervorgang."] = "Kasa ve TV aynı Wi-Fi/ağda olmalı. TV'de internet tarayıcısını açın (Samsung: Internet, LG: Web Tarayıcı, Android TV: ör. bir kiosk tarayıcı) ve yukarıdaki adresi girin. Reklam görselleri müşteri ekranındakilerle aynıdır; içerik ve değişim süresi burada ayrı ayarlanır. İlk başlatmada Windows güvenlik duvarı için soru sorabilir: özel ağlarda erişime izin verin. Sayfaya yalnızca kendi ağınızdan erişilebilir; fişi, TSE'yi ve ödeme işlemini etkilemez.",
        ["Neue TV-Adresse erzeugt - am TV neu eingeben"] = "Yeni TV adresi oluşturuldu - TV'de yeniden girin",
        ["TV-Adresse konnte nicht ermittelt werden"] = "TV adresi belirlenemedi",
        ["Die TV-Adresse erscheint nach dem Einschalten und Speichern."] = "TV adresi, özellik açılıp kaydedildikten sonra görünür.",
        ["Kein lokales Netzwerk gefunden. Kasse mit dem WLAN/LAN des TVs verbinden."] = "Yerel ağ bulunamadı. Kasayı TV'nin bağlı olduğu Wi-Fi/LAN'a bağlayın.",
        ["Am TV im Browser eingeben"] = "TV'de tarayıcıya girin",
        ["WERBE-TV: Der gewählte TV-Port ist belegt oder gesperrt. In Einstellungen einen anderen TV-Port wählen."] = "REKLAM TV: Seçilen TV portu kullanımda veya engelli. Ayarlarda başka bir TV portu seçin.",
        ["KASSENABSCHLUSS NACH UPDATE NÖTIG"] = "GÜNCELLEME SONRASI KASA KAPANIŞI GEREKLİ",
        ["TOR POS wurde aktualisiert, aber der automatische Kassenabschluss war nicht möglich, weil noch geparkte Bons oder ein offener Vorgang vorhanden waren. Bitte offene Bons kassieren und heute einen Z-Abschluss durchführen."] = "TOR POS güncellendi, ancak park edilmiş fişler veya açık bir işlem olduğu için otomatik kasa kapanışı yapılamadı. Lütfen açık fişleri tahsil edin ve bugün bir Z-Abschluss yapın.",
        ["Kopplungscode vom Solo (nur bei neuer Kopplung)"] = "Solo'dan eşleştirme kodu (yalnızca yeni eşleştirmede)",
        ["Geräteliste laden, danach Solo auswählen"] = "Cihaz listesini yükleyin, sonra Solo'yu seçin",
        ["Verbindungstest. Der 1,00-€-Test sendet eine ECHTE Zahlungsanforderung an das Solo. KEINE KARTE vorhalten; danach ABBRECHEN."] =
            "Bağlantı testi. 1,00 € testi Solo'ya GERÇEK bir ödeme isteği gönderir. KART OKUTMAYIN; ardından İPTAL edin.",
        ["WICHTIG: 1,00 € SENDEN dient nur dazu zu prüfen, ob der Betrag auf dem Solo erscheint. Wenn eine Karte vorgehalten wird, kann eine echte Zahlung entstehen. Sobald 1,00 € am Solo sichtbar ist, TEST ABBRECHEN drücken oder direkt am Solo abbrechen."] =
            "ÖNEMLİ: 1,00 € GÖNDER yalnızca tutarın Solo'da görünüp görünmediğini kontrol etmek içindir. Kart okutulursa gerçek bir ödeme oluşabilir. Solo'da 1,00 € görünür görünmez TESTİ İPTAL ET'e basın veya doğrudan Solo'dan iptal edin.",
        ["Neues Gerät: Solo abmelden → Verbindungen / Connections → API → Verbinden / Connect. Code innerhalb von 5 Minuten verwenden."] =
            "Yeni cihaz: Solo'dan çıkış yapın → Bağlantılar / Connections → API → Bağlan / Connect. Kodu 5 dakika içinde kullanın.",
        ["SUMUP SOLO · VERBINDUNG + 1,00 € TEST"] = "SUMUP SOLO · BAĞLANTI + 1,00 € TEST",
        ["KARTE TEST im normalen Kassenbild bleibt Simulation. Dieser separate Admin-Test sendet nur eine feste 1,00-€-Anforderung an das ausgewählte Solo; Zugangsdaten werden nicht gespeichert."] =
            "Normal kasa ekranındaki KART TEST simülasyon olarak kalır. Bu ayrı yönetici testi, seçilen Solo'ya yalnızca sabit bir 1,00 € isteği gönderir; erişim bilgileri kaydedilmez.",
        ["SumUp Solo · Verbindung + 1,00 € Gerätetest"] = "SumUp Solo · bağlantı + 1,00 € cihaz testi",
        ["ALLE BENUTZER SPEICHERN"] = "TÜM KULLANICILARI KAYDET",
        ["ADMIN-ZUGANG ÄNDERN"] = "YÖNETİCİ ERİŞİMİNİ DEĞİŞTİR",
        ["Benutzer aktiv"] = "Kullanıcı etkin",
        ["MITARBEITER & RECHTE"] = "PERSONEL VE YETKİLER",
        ["Neben dem Admin stehen genau drei Mitarbeiterkonten bereit. "] =
            "Yöneticinin yanında tam olarak üç personel hesabı hazırdır. ",
        ["ADMIN-ZUGANG"] = "YÖNETİCİ ERİŞİMİ",
        ["Standard bei einer neuen Installation: Benutzer admin · Passwort admin · PIN 1234. "] =
            "Yeni kurulumda varsayılan: kullanıcı admin · şifre admin · PIN 1234. ",
        ["Aktuelles Admin-Passwort"] = "Geçerli yönetici şifresi",
        ["Neues Admin-Passwort"] = "Yeni yönetici şifresi",
        ["Neue 4-stellige Admin-PIN"] = "Yeni 4 haneli yönetici PIN'i",
        ["Berechtigungen"] = "Yetkiler",
        ["Einstellungen und Benutzerverwaltung bleiben immer ausschließlich beim Admin."] =
            "Ayarlar ve kullanıcı yönetimi her zaman yalnızca yöneticide kalır.",
        ["TOR POS – Mitarbeiter & Rechte"] = "TOR POS – personel ve yetkiler",
        ["Automatische Kartenterminal-Anbindung aktivieren"] = "Otomatik kart terminali bağlantısını etkinleştir",
        ["PROFIL SPEICHERN"] = "PROFİLİ KAYDET",
        ["SUMUP GERÄT / PAIRING ÖFFNEN"] = "SUMUP CİHAZI / EŞLEŞTİRMEYİ AÇ",
        ["Modell / eigene Notiz (optional)"] = "Model / kendi notunuz (isteğe bağlı)",
        ["z. B. 192.168.1.50"] = "ör. 192.168.1.50",
        ["IP und Port stehen je nach Anbieter im Terminalmenü. Häufig ist der ZVT-Port 20007; maßgeblich ist immer die tatsächliche Terminalkonfiguration."] =
            "IP ve port, sağlayıcıya göre terminal menüsünde yazar. ZVT portu çoğunlukla 20007'dir; belirleyici olan her zaman gerçek terminal yapılandırmasıdır.",
        ["KARTENTERMINAL VERBINDEN"] = "KART TERMİNALİNİ BAĞLA",
        ["Marke bzw. Terminalfamilie auswählen. TOR zeigt nur die Angaben, die für diesen Integrationsweg benötigt werden. Ein gelisteter Hersteller bedeutet nicht automatisch, dass dessen proprietäre Schnittstelle ohne Providerfreigabe verwendet werden darf."] =
            "Markayı veya terminal ailesini seçin. TOR yalnızca bu entegrasyon yolu için gereken bilgileri gösterir. Listelenen bir üretici, o üreticinin özel arayüzünün sağlayıcı onayı olmadan kullanılabileceği anlamına gelmez.",
        ["Sicherheitsregel: TOR POS speichert keine vollständige Kartennummer, keine PIN und keinen CVV/CVC. Nicht freigegebene Providerprofile bleiben automatisch deaktiviert; TOR startet darüber keine vermeintliche Zahlung."] =
            "Güvenlik kuralı: TOR POS tam kart numarası, PIN ve CVV/CVC saklamaz. Onaylanmamış sağlayıcı profilleri otomatik olarak kapalı kalır; TOR bunlar üzerinden sözde bir ödeme başlatmaz.",
        ["TOR POS · Kartenterminal-Assistent"] = "TOR POS · kart terminali sihirbazı",
