        ["Für E-Mail packt TOR den vollständigen Export in eine ZIP-Datei und verwendet den unter Berichte & E-Mail aktiven Versandweg (TOR Mail, Google oder SMTP). Die Empfänger-Adresse kann für diesen Versand frei geändert werden."] =
            "E-posta için TOR, dışa aktarımın tamamını bir ZIP dosyasına koyar ve Raporlar ve e-posta altında etkin olan gönderim yolunu kullanır (TOR Mail, Google veya SMTP). Alıcı adresi bu gönderim için serbestçe değiştirilebilir.",
        ["E-Mail-Hinweis: Große Prüfdatensätze können Mail-Größenlimits überschreiten. TOR versendet deshalb keine ZIP-Datei über 15 MB; in diesem Fall USB/Datenträger verwenden."] =
            "E-posta notu: Büyük denetim veri kümeleri posta boyut sınırlarını aşabilir. Bu yüzden TOR 15 MB üzerindeki ZIP dosyalarını göndermez; bu durumda USB/veri taşıyıcı kullanın.",
