        // Settings · navigation and reports/email
        ["Kasse & Bedienung"] = "Till & operation",
        ["Firma & Bon"] = "Company & receipt",
        ["Artikel & Steuern"] = "Items & taxes",
        ["Berichte & E-Mail"] = "Reports & email",
