        ["Erweitert / Techniker 🔒"] = "Advanced / Technician 🔒",
        ["Erweitert / Techniker"] = "Advanced / Technician",
        ["Alle Standardberichte können als PDF gespeichert werden. Optional verschickt TOR POS einmal pro Monat automatisch ein PDF-Paket per E-Mail."] = "All standard reports can be saved as PDF. Optionally, TOR POS automatically sends a PDF package by email once a month.",
        ["Monatlicher PDF-Versand"] = "Monthly PDF delivery",
        ["Monatliche Berichte automatisch per E-Mail senden"] = "Automatically email monthly reports",
        ["Empfänger-E-Mail"] = "Recipient email",
        ["Diese Adresse erhält das monatliche PDF-Paket."] = "This address receives the monthly PDF package.",
        ["Versandtag"] = "Delivery day",
        ["1–28 · Standard 1. Versendet den abgeschlossenen Vormonat."] = "1–28 · Default 1. Sends the completed previous month.",
        ["Versandzeit"] = "Delivery time",
        ["HH:mm · Standard 00:15. Bei ausgeschaltetem TOR POS wird der verpasste Versand nach dem nächsten Start nachgeholt."] = "HH:mm · Default 00:15. If TOR POS was off, the missed delivery is sent after the next start.",
        ["Sicherheitsregel"] = "Safety rule",
        ["Der E-Mail-Versand erzeugt KEINEN Z-Bericht, keinen Tagesabschluss und keinen Kassenabschluss."] = "Email delivery does NOT create a Z-Bericht, day close or till close.",
        ["TOR Mail · empfohlen · keine Google-/SMTP-Einrichtung"] = "TOR Mail · recommended · no Google/SMTP setup",
        ["Der Kunde trägt nur die Empfänger-E-Mail ein. Der Absender und die SMTP-Zugangsdaten liegen ausschließlich auf dem TOR POS Cloud-Server und werden niemals auf der Kasse gespeichert."] = "The customer enters only the recipient email. The sender and SMTP credentials exist only on the TOR POS Cloud server and are never stored on the till.",
        ["TOR MAIL ALS VERSANDWEG VERWENDEN"] = "USE TOR MAIL FOR DELIVERY",
        ["TOR MAIL TEST-E-MAIL SENDEN"] = "SEND TOR MAIL TEST EMAIL",
        ["Voraussetzung: TOR POS Cloud muss unter Geräte eingerichtet sein. Der zentrale Mail-Absender wird einmalig von TOR auf dem Cloud-Server konfiguriert; der Kunde benötigt dafür kein Google-Konto, App-Passwort oder SMTP-Wissen."] = "Requirement: TOR POS Cloud must be configured under Devices. TOR configures the central mail sender once on the Cloud server; the customer needs no Google account, app password or SMTP knowledge.",
        ["Google-Konto / Gmail API (Alternative)"] = "Google account / Gmail API (alternative)",
        ["Kein Gmail-Passwort und kein App-Passwort in TOR POS: MIT GOOGLE ANMELDEN erzeugt einen einmaligen QR-Code. Der Inhaber scannt ihn mit dem Handy und bestätigt die Berechtigung direkt bei Google."] = "TOR POS stores no Gmail password or app password: SIGN IN WITH GOOGLE creates a one-time QR code. The owner scans it on a phone and confirms permission directly with Google.",
        ["MIT GOOGLE ANMELDEN (QR)"] = "SIGN IN WITH GOOGLE (QR)",
        ["GOOGLE TEST-E-MAIL SENDEN"] = "SEND GOOGLE TEST EMAIL",
        ["GOOGLE-VERBINDUNG TRENNEN"] = "DISCONNECT GOOGLE",
        ["Voraussetzung für QR-Anmeldung: TOR POS Cloud muss unter Geräte eingerichtet sein und der Cloud-Server benötigt eine freigegebene Google-OAuth-Konfiguration. Die Monatsberichte selbst gehen direkt von diesem PC an die Gmail API; die PDF-Dateien werden nicht über TOR POS Cloud geleitet."] = "For QR sign-in, TOR POS Cloud must be configured under Devices and the Cloud server needs an approved Google OAuth configuration. Monthly reports go directly from this PC to the Gmail API; PDF files are not routed through TOR POS Cloud.",
        ["Eigener E-Mail-Ausgang / SMTP (Alternative)"] = "Own email delivery / SMTP (alternative)",
        ["Absender-E-Mail"] = "Sender email",
        ["Für Gmail: smtp.gmail.com"] = "For Gmail: smtp.gmail.com",
        ["Für Gmail: 587 (STARTTLS)."] = "For Gmail: 587 (STARTTLS).",
        ["TLS/SSL verwenden"] = "Use TLS/SSL",
        ["SMTP-Benutzer"] = "SMTP user",
        ["Bei Gmail die vollständige Gmail-/Google-Workspace-Adresse."] = "For Gmail, use the full Gmail/Google Workspace address.",
        ["SMTP App-Passwort"] = "SMTP app password",
        ["Leer lassen, um ein bereits gespeichertes App-Passwort zu behalten. Google-App-Passwort-Leerzeichen werden automatisch entfernt."] = "Leave blank to keep an already stored app password. Spaces in Google app passwords are removed automatically.",
        ["GMAIL-STANDARD ÜBERNEHMEN"] = "APPLY GMAIL DEFAULTS",
        ["SMTP ALS VERSANDWEG VERWENDEN"] = "USE SMTP FOR DELIVERY",
        ["Noch kein E-Mail-Test ausgeführt."] = "No email test has been run yet.",
        ["TEST-E-MAIL SENDEN"] = "SEND TEST EMAIL",
        ["SMTP-Diagnose"] = "SMTP diagnostics",
        ["App-Passwort wird niemals in diesem Feld oder im Audit-Log ausgegeben."] = "The app password is never shown in this field or in the Audit Log.",
        ["Letzter automatischer Versand"] = "Last automatic delivery",
