        ["Lokales PDF-Paket"] = "Local PDF package",
        ["Die versendeten PDFs bleiben zusätzlich lokal im Reports-Ordner gespeichert."] = "Sent PDFs are also kept locally in the Reports folder.",
        ["Welche PDFs werden monatlich versendet?"] = "Which PDFs are sent monthly?",
        ["Monatsübersicht, Kassenjournal, Verkaufsstatistik, Bedienerabrechnung, Stornobericht, vorhandenes Z-Archiv und ein aktueller Warenbestands-Snapshot. Es wird niemals automatisch ein neuer Z-Abschluss erzeugt."] = "Monthly overview, Kassenjournal, sales statistics, Bedienerabrechnung, Stornobericht, existing Z archive and a current stock snapshot. A new Z-Abschluss is never created automatically.",
