        ["Steuernummer"] = "Tax number",
        ["USt-IdNr."] = "VAT ID",
        ["Verwendung"] = "Usage",
        ["Firmendaten auf dem Bon verwenden"] = "Use company data on receipt",
        ["Firmendaten auf Berichten verwenden"] = "Use company data on reports",
        ["Bedienfunktionen"] = "Operator functions",
        ["Nur Funktionen einschalten, die der Betrieb tatsächlich benutzt."] = "Enable only functions the business actually uses.",
        ["Verkauf"] = "Sale",
        ["Sonstige Artikel / freie Preiseingabe anzeigen"] = "Show miscellaneous item / free price entry",
        ["Pfand / Leergut anzeigen"] = "Show deposit / empties",
        ["Gastronomie · Extras"] = "Hospitality · Extras",
        ["Verwaltung direkt im Artikel / unter STAMMDATEN → EXTRAS"] = "Manage directly in the item / under MASTER DATA → EXTRAS",
        ["Bei kritischem Warenbestand warnen"] = "Warn on critical stock",
        ["Mindestbestand"] = "Minimum stock",
        ["Warnschwelle, z.B. 5 Stück."] = "Warning threshold, e.g. 5 units.",
        ["Abholnummer / Bestellablauf"] = "Pickup number / order flow",
        ["Schnellauswahl"] = "Quick selection",
        ["OFF = aus · SALE = Nummer beim Kassieren · ORDER = Nummer sofort bei Bestellannahme"] = "OFF = off · SALE = number at checkout · ORDER = number immediately when accepting the order",
        ["Empfohlen für Gastronomie mit Bestell-/Abholablauf (z. B. Döner, Imbiss, Café, Restaurant): ORDER. Dann erscheint in der Kasse BESTELLUNG ANNEHMEN · F3 · ABHOLNR.; der eigentliche Bon entsteht erst später bei BAR/KARTE."] = "Recommended for hospitality with order/pickup flow (e.g. kebab shop, snack bar, café, restaurant): ORDER. The till shows BESTELLUNG ANNEHMEN · F3 · ABHOLNR.; the actual receipt is created later at BAR/KARTE.",
        ["Bei Bestellannahme eine Abholnummer vergeben"] = "Assign a pickup number when accepting an order",
        ["Bei ORDER einen Abholschein für den Kunden drucken"] = "Print a pickup slip for the customer in ORDER",
        ["Training"] = "Training",
        ["ORDER kann jetzt auch mit dem TRAINING-Benutzer getestet werden. Trainingsbestellungen und Trainings-Abholnummern bleiben getrennt von echten offenen Bestellungen."] = "ORDER can also be tested with the TRAINING user. Training orders and pickup numbers stay separate from real open orders.",
        ["Wichtig"] = "Important",
        ["Abholnummer ist nur eine Betriebs-/Wartenummer und ersetzt niemals die Bonnummer."] = "The pickup number is only an operational/queue number and never replaces the receipt number.",
        // The TSE outage list. The recorded reason itself is never translated -
        // it is the documented cause of a fiscal outage and reaches a Pruefer
        // exactly as the till wrote it.
        ["TSE-Ausfälle"] = "TSE outages",
        ["Jeder Ausfall wird mit Beginn, Ende und Grund protokolliert und kann nicht gelöscht werden. Dieselben Daten gehen in den DSFinV-K-Export."] =
            "Every outage is logged with start, end and reason and cannot be deleted. The same data goes into the DSFinV-K export.",
        ["AUSFALLLISTE AKTUALISIEREN"] = "REFRESH OUTAGE LIST",
        ["Ausfallliste wird gelesen ..."] = "Reading the outage list ...",
        ["Kein TSE-Ausfall protokolliert."] = "No TSE outage logged.",
        ["Ausfallliste konnte nicht gelesen werden."] = "The outage list could not be read.",
        // The TSE clock. "TimeAdmin" is the name Swissbit gives that PIN and
        // stays as it is, like TSE itself.
        ["TSE-Uhrzeit"] = "TSE clock",
        ["Warum"] = "Why",
        ["Eine TSE signiert nicht mehr, sobald ihre eigene Uhr ungültig ist. Das passiert nach längerer Lagerung oder wenn die Kasse lange ausgeschaltet war."] =
            "A TSE stops signing once its own clock is no longer valid. That happens after long storage or when the till was switched off for a long time.",
        ["TimeAdmin-PIN ist auf dieser Kasse gespeichert"] = "The TimeAdmin PIN is stored on this till",
        ["Nur die TimeAdmin-PIN. Sie kann ausschließlich die Uhr stellen - keine PIN ändern, keinen Client registrieren, die TSE nicht außer Betrieb setzen. Admin-PIN, PUK und Credential-Seed werden nirgends gespeichert."] =
            "The TimeAdmin PIN only. It can set the clock and nothing else - it cannot change a PIN, register a client or decommission the TSE. The Admin PIN, the PUK and the credential seed are never stored.",
        ["PIN SPEICHERN"] = "SAVE PIN",
        ["GESPEICHERTE PIN LÖSCHEN"] = "DELETE STORED PIN",
        ["Keine TimeAdmin-PIN eingegeben."] = "No TimeAdmin PIN entered.",
        ["TimeAdmin-PIN gespeichert. Die TSE-Uhr wird jetzt automatisch nachgeführt."] =
            "TimeAdmin PIN stored. The TSE clock is now kept up to date automatically.",
        ["Gespeicherte TimeAdmin-PIN gelöscht."] = "Stored TimeAdmin PIN deleted.",
        // Cloud TSE. "TSE", "Cloud-TSE", "Queue", "API" and the vendor names
        // stay as they are: a technician and the vendor's contract use them.
        ["Art der TSE"] = "Type of TSE",
        ["Auswahl"] = "Choice",
        ["SWISSBIT_USB = TSE steckt als USB-Stick in dieser Kasse. CLOUD = zertifizierte TSE eines Anbieters über HTTPS. Die Umstellung wirkt erst nach einem Neustart."] =
            "SWISSBIT_USB = the TSE is plugged into this till as a USB stick. CLOUD = a vendor's certified TSE over HTTPS. The change takes effect after a restart.",
        ["Ein unbekannter Wert fällt auf SWISSBIT_USB zurück. Eine Kasse wird nie stillschweigend auf ein anderes Fiskalgerät umgestellt."] =
            "An unknown value falls back to SWISSBIT_USB. A till is never moved onto a different fiscal device silently.",
        ["Cloud-TSE"] = "Cloud TSE",
        ["Freigabe"] = "Release",
        ["Cloud-TSE ist für diesen Anbieter freigegeben."] = "Cloud TSE is released for this vendor.",
        ["Cloud-TSE ist für diesen Anbieter NICHT freigegeben. Einstellungen können erfasst und der Endpunkt geprüft werden; es wird nichts signiert."] =
            "Cloud TSE is NOT released for this vendor. Settings can be entered and the endpoint tested; nothing is signed.",
        ["Mandant / Queue"] = "Tenant / queue",
        ["Mandant und Queue gehören zusammen und müssen zu dieser Kasse passen. Die gefährlichste Verwechslung bei einer Cloud-TSE ist eine Kasse, die in die Queue eines fremden Mandanten signiert: die Belege sehen gültig aus und gehören in fremde Bücher."] =
            "Tenant and queue belong together and must match this till. The most dangerous mix-up with a cloud TSE is a till signing into another tenant's queue: the receipts look valid and belong in somebody else's books.",
        ["Anbieter"] = "Vendor",
        ["Endpunkt"] = "Endpoint",
        ["Mandant"] = "Tenant",
        ["Queue"] = "Queue",
        ["API-Schlüssel"] = "API key",
        ["Der zertifizierte Cloud-TSE-Anbieter, mit dem ein Vertrag besteht. Jeder Anbieter wird einzeln freigegeben: die Freigabe eines Anbieters öffnet keinen anderen."] =
            "The certified cloud TSE vendor you hold a contract with. Each vendor is released on its own: releasing one opens no other.",
        ["Vollständige HTTPS-Adresse. Andere Protokolle werden abgelehnt."] = "Full HTTPS address. Other protocols are rejected.",
        ["Muss die Kassen-Seriennummer sein - dieselbe Nummer wie auf dem Bon und im DSFinV-K-Export."] =
            "Must be the till serial number - the same number as on the receipt and in the DSFinV-K export.",
        ["Wird DPAPI-geschützt gespeichert und nie im Klartext abgelegt oder protokolliert."] =
            "Stored DPAPI-protected and never written or logged in clear text.",
        ["CLOUD-TSE VERBINDUNG PRÜFEN"] = "TEST CLOUD TSE CONNECTION",
        ["Cloud-TSE Endpunkt wird geprüft ..."] = "Checking the cloud TSE endpoint ...",
        ["läuft noch"] = "still open",
        ["Tag"] = "day",
        ["Tage"] = "days",
        ["Std."] = "h",
        ["Min."] = "min",
        ["Tagesabschluss"] = "Day close",
        ["Z-Bericht automatisch drucken"] = "Print Z-Bericht automatically",
        ["Z-Abschluss bleibt bei offenen geparkten Bons gesperrt."] = "Z-Abschluss remains locked while parked receipts are open.",
        ["Zahlarten"] = "Payment methods",
        ["Zahlarten werden separat konfiguriert. Die Karten-Zahlart wird später direkt mit ZVT verbunden."] = "Payment methods are configured separately. The card method is later connected directly to ZVT.",
        ["Aktive Zahlarten"] = "Active payment methods",
        ["Bar aktiv"] = "Cash active",
        ["Karte aktiv"] = "Card active",
        ["Auf Rechnung aktiv"] = "Invoice active",
        ["Bezeichnung Bar"] = "Cash label",
        ["Bezeichnung Karte"] = "Card label",
        ["Bezeichnung Rechnung"] = "Invoice label",
        ["Schnellkassieren · F5"] = "Quick checkout · F5",
        ["Standard-Zahlart"] = "Default payment method",
        ["AUS = F5 öffnet die Zahlart-Auswahl. BAR/KARTE = F5 startet die gewählte Zahlart direkt."] = "OFF = F5 opens payment-method selection. BAR/KARTE = F5 starts the selected method directly.",
        ["Bei F5 + BAR sofort als PASSEND kassieren (kein Rückgeld-Dialog)"] = "With F5 + BAR, checkout immediately as EXACT (no change dialog)",
        ["F1 BAR bleibt immer die normale Barzahlung mit Gegeben/Rückgeld. F2 KARTE bleibt direkte Kartenzahlung. Die gespeicherte Zahlart ist auch beim Schnellkassieren immer eindeutig BAR oder KARTE."] = "F1 BAR always remains normal cash payment with amount given/change. F2 KARTE remains direct card payment. The stored payment method is always unambiguously BAR or KARTE even in quick checkout.",
        ["Angebote / Rabatte"] = "Offers / discounts",
        ["Manuellen Rabatt zusätzlich zu einem aktiven Angebot erlauben"] = "Allow a manual discount in addition to an active offer",
        ["Standard"] = "Default",
        ["AUS empfohlen: Angebot und manueller Rabatt werden nicht automatisch gestapelt. Pfand wird niemals durch Angebot rabattiert."] = "OFF recommended: offer and manual discount are not stacked automatically. Deposit is never discounted by an offer.",
        ["Kartenzahlung"] = "Card payment",
        ["Bei aktivierter Terminalintegration wird ein Kartenverkauf erst nach erfolgreicher Terminalbestätigung als Verkauf gespeichert."] = "With terminal integration enabled, a card sale is saved only after successful terminal confirmation.",

        // Settings · devices, Cloud, backup and staff
        ["Drucker & Geräte"] = "Printers & devices",
        ["Windows-Drucker auswählen, testen und unten SPEICHERN drücken. Das Kartenterminal wird über den Marken-Assistenten verbunden."] = "Select and test the Windows printer, then press SAVE below. The card terminal is connected through the brand assistant.",
        ["WAAGEN-EINSTELLUNGEN · MANUELL / COM / LAN / BARCODE"] = "SCALE SETTINGS · MANUAL / COM / LAN / BARCODE",
        ["Gewichtsverkauf"] = "Weighted sales",
        ["Gewichtsartikel werden intern in kg geführt. Eine separate Waage ohne Kassenanschluss ist vollständig nutzbar: Gewicht ablesen und beim Verkauf in Gramm oder Kilogramm eingeben. COM/LAN/Waagenbarcode können zusätzlich vorbereitet werden."] = "Weighted items are stored internally in kg. A separate scale without till connection is fully usable: read the weight and enter grams or kilograms during the sale. COM/LAN/scale barcode can also be prepared.",
        ["DRUCKER-ZENTRALE · EPSON / STAR AUTOMATISCH ERKENNEN"] = "PRINTER CENTRE · AUTO-DETECT EPSON / STAR",
        ["Automatische Druckererkennung"] = "Automatic printer detection",
        ["TOR liest die in Windows installierten Drucker, Treiber und Ports und erkennt verbreitete Epson-TM- sowie Star-mC/TSP-Bondrucker. Ein konkretes Modell wird nur bei eindeutiger Kennung übernommen; bei unklarem Modell muss der Benutzer die Auswahl bestätigen."] = "TOR reads printers, drivers and ports installed in Windows and detects common Epson-TM and Star-mC/TSP receipt printers. A specific model is accepted only when clearly identified; otherwise the user must confirm the choice.",
        ["KARTENTERMINAL VERBINDEN · MARKE AUSWÄHLEN"] = "CONNECT CARD TERMINAL · SELECT BRAND",
        ["Terminal-Assistent"] = "Terminal assistant",
        ["Bondrucker"] = "Receipt printer",
        ["Küchendrucker / 2. Drucker"] = "Kitchen printer / 2nd printer",
        ["Bestellung automatisch an Küchendrucker senden"] = "Automatically send order to kitchen printer",
        ["Küchenbon"] = "Kitchen ticket",
        ["Küchenbons bleiben immer auf Deutsch und sind klar als KEIN STEUERBELEG gekennzeichnet. Im ORDER-Modus wird die Küche direkt bei Bestellannahme informiert; OFF/SALE drucken erst beim Kassieren."] = "Kitchen tickets always remain in German and are clearly marked KEIN STEUERBELEG. In ORDER mode the kitchen is notified when the order is accepted; OFF/SALE print only at checkout.",
        ["Küchenrouting nach Station"] = "Kitchen routing by station",
        ["Küchendrucker · Grill"] = "Kitchen printer · Grill",
        ["Küchendrucker · Fritteuse"] = "Kitchen printer · Fryer",
        ["Küchendrucker · Getränke"] = "Kitchen printer · Drinks",
        ["A4-Drucker"] = "A4 printer",
        ["GERÄTESTATUS AKTUALISIEREN"] = "REFRESH DEVICE STATUS",
        ["Terminal & TSE"] = "Terminal & TSE",
        ["Kassenlade verwenden"] = "Use cash drawer",
        ["Kassenschublade · Verbindungstest"] = "Cash drawer · connection test",
        ["Noch nicht getestet. Der Test erzeugt keinen Verkauf und keinen Bon."] = "Not tested yet. The test creates no sale and no receipt.",
        ["KASSENSCHUBLADE TESTEN"] = "TEST CASH DRAWER",
        ["Der Test sendet genau einen ESC-p/StarPRNT-Impuls über den ausgewählten Bondrucker. Kein Verkauf, keine TSE-Transaktion, kein Bon."] = "The test sends exactly one ESC-p/StarPRNT pulse through the selected receipt printer. No sale, no TSE transaction, no receipt.",
        ["Kundendisplay verwenden"] = "Use customer display",
        ["Kundendisplay · eigener Bildschirm"] = "Customer display · separate screen",
        ["Bildschirm"] = "Screen",
        ["0 = automatisch einen zweiten Bildschirm (nie den Kassenbildschirm); 1 = Windows-Hauptbildschirm, 2–4 = weitere Bildschirme von links nach rechts."] = "0 = automatically a second screen (never the till screen); 1 = Windows primary screen, 2–4 = further screens from left to right.",
        ["Getrennt vom Bestellmonitor"] = "Separate from order monitor",
        ["Separaten Bestellmonitor verwenden"] = "Use separate order monitor",
        ["Bestellmonitor · eigener Bildschirm"] = "Order monitor · separate screen",
        ["Aktualisierung (Sek.)"] = "Refresh (sec.)",
        ["1–10 Sekunden · Standard 2."] = "1–10 seconds · Default 2.",
        ["Nur Bestellungen"] = "Orders only",
        ["TOR POS Cloud · Synchronisierung"] = "TOR POS Cloud · synchronization",
        ["Verbindung und Bestand direkt mit dem Kundenportal prüfen. Testbons werden nicht als Umsatz übertragen."] = "Check connection and stock directly with the customer portal. Test receipts are not transmitted as turnover.",
        ["Leer lassen: gespeichertes Token behalten"] = "Leave blank: keep stored token",
        ["Synchronisierung aktivieren"] = "Enable synchronization",
        ["Cloud wird geladen …"] = "Loading Cloud …",
        ["Cloud-Verbindung"] = "Cloud connection",
        ["Server-URL"] = "Server URL",
        ["Gleicher PC: http://127.0.0.1:8787. Andere Server benötigen HTTPS."] = "Same PC: http://127.0.0.1:8787. Other servers require HTTPS.",
        ["Gerätecode"] = "Device code",
        ["Das Ziel bleibt für wartende Daten fest zugeordnet."] = "The target remains fixed for queued data.",
        ["Gerätetoken"] = "Device token",
        ["Verschlüsselt für dieses Windows-Benutzerkonto gespeichert. Nicht im Chat teilen."] = "Stored encrypted for this Windows user account. Do not share it in chat.",
