        ["Performance"] = "Performance",
        ["Backups sind vom Verkaufspfad getrennt und können auf ein anderes Laufwerk oder einen Serverordner geschrieben werden."] = "Backups are separate from the sales path and can be written to another drive or server folder.",
        ["Backup"] = "Backup",
