        ["Uhrzeit"] = "Time",
        ["HH:mm · Standard 00:00. Erzeugt keinen Z-Bericht und keinen Kassenabschluss."] = "HH:mm · Default 00:00. Creates no Z-Bericht and no till close.",
        ["Letzte erfolgreiche Sicherung"] = "Last successful backup",
        ["Wenn TOR POS zur Uhrzeit geschlossen war, wird die verpasste Sicherung beim nächsten Start nachgeholt."] = "If TOR POS was closed at the scheduled time, the missed backup runs after the next start.",
        ["Bei nicht erreichbarem Laufwerk bleibt der Erfolgszeitpunkt unverändert; TOR versucht nach fünf Minuten erneut."] = "If the drive is unavailable, the last-success time stays unchanged; TOR retries after five minutes.",
