        ["Drei Mitarbeiterkonten mit eigenen Zugangsdaten und einzeln einstellbaren Funktionsrechten."] = "Three staff accounts with their own credentials and individually configurable function permissions.",
        ["Admin + 3 Mitarbeiter"] = "Admin + 3 staff",
        ["Admin"] = "Admin",
