        ["TRAINING-CODE SPEICHERN"] = "SAVE TRAINING CODE",
        ["Gilt nur für die Trainingsanmeldung ohne Benutzerpasswort. Trainingsverkäufe werden nie gebucht, signiert oder an die Cloud gemeldet."] = "Applies only to training sign-in without a user password. Training sales are never booked, signed or reported to the Cloud.",
