        // Technikerbereich: Software & Update, System, Kasse, Geräte, Buchhaltung
        ["Version, Lizenzlaufzeit und Updates ohne technische Server-Einstellungen prüfen."] =
            "Check the version, the licence period and updates without touching technical server settings.",
        ["Installierte TOR-POS-Version"] = "Installed TOR POS version",
        ["Version"] = "Version",
        ["Build"] = "Build",
        ["Edition"] = "Edition",
        ["Gültig bis"] = "Valid until",
