        ["TOR Update"] = "TOR Update",
        ["Automatisch alle 6 Stunden nach Updates suchen"] = "Look for updates automatically every 6 hours",
        ["Update-Status wird geladen …"] = "Loading the update status …",
        ["AUTOMATISCHE PRÜFUNG SPEICHERN"] = "SAVE THE AUTOMATIC CHECK",
        ["JETZT NACH UPDATE SUCHEN"] = "LOOK FOR AN UPDATE NOW",
        ["Automatische Update-Prüfung ist aktiv."] = "The automatic update check is active.",
        ["Automatische Update-Prüfung ist deaktiviert. Manuelle Prüfung bleibt möglich."] =
            "The automatic update check is off. A manual check is still possible.",
        ["Noch keine Update-Prüfung."] = "No update check yet.",
        ["Letzte Prüfung"] = "Last check",
        ["Neue Version verfügbar"] = "A new version is available",
        ["WICHTIGES UPDATE"] = "IMPORTANT UPDATE",
        ["Zur Kasse zurückkehren: oben erscheint für Admin der UPDATE-Button. Installation startet erst nach Sicherheitsprüfung und Backup."] =
            "Go back to the till: the UPDATE button appears at the top for the admin. Installation starts only after the security check and the backup.",
        ["Update-Einstellung"] = "Update setting",
        ["Update-Prüfung"] = "Update check",
        ["Update-Status"] = "Update status",
        ["Sicher aktualisieren"] = "Updating safely",
        ["TOR POS installiert niemals mitten in einem Verkauf oder einer ungeklärten Zahlung. Vor der Installation werden Setup-Prüfsumme/Signatur geprüft und eine Datenbanksicherung erstellt. Die technische Update-Server-Adresse bleibt im geschützten Technikerbereich."] =
            "TOR POS never installs in the middle of a sale or an unclear payment. Before installing, the setup checksum and signature are verified and a database backup is made. The technical update server address stays in the protected technician area.",
        ["System"] = "System",
        ["Technische Informationen für Installation, Service und Diagnose."] =
            "Technical information for installation, service and diagnosis.",
        ["Installation"] = "Installation",
        ["Datenordner"] = "Data folder",
        ["Datenbank"] = "Database",
        ["Schema-Migration"] = "Schema migration",
        ["Produktbilder"] = "Product images",
        ["Backups"] = "Backups",
        ["TOR Update · Technische Quelle"] = "TOR Update · technical source",
        ["Leer = TOR Cloud Server verwenden"] = "Empty = use the TOR Cloud server",
        ["Update-Server wird geladen …"] = "Loading the update server …",
        ["Update-Server"] = "Update server",
        ["Nur für Installation/Service. Produktiv ausschließlich HTTPS; localhost darf für Entwicklung HTTP verwenden."] =
            "For installation and service only. In production HTTPS only; localhost may use HTTP for development.",
        ["UPDATE-SERVER SPEICHERN"] = "SAVE THE UPDATE SERVER",
        ["Gespeichert: TOR Cloud Server wird als Update-Quelle verwendet."] =
            "Saved: the TOR Cloud server is used as the update source.",
        ["Technische Update-Quelle gespeichert."] = "The technical update source has been saved.",
        ["Keine separate Update-Quelle: TOR Cloud Server wird verwendet."] =
            "No separate update source: the TOR Cloud server is used.",
        ["Separate technische Update-Quelle ist konfiguriert."] = "A separate technical update source is configured.",
        ["Performance & Diagnose"] = "Performance & diagnosis",
        ["Bewertung"] = "Rating",
        ["Noch keine Messwerte vorhanden."] = "There are no measurements yet.",
        ["SYSTEMSTATUS / DIAGNOSE ÖFFNEN"] = "OPEN SYSTEM STATUS / DIAGNOSIS",
        ["Fiskalstatus"] = "Fiscal status",
        ["Swissbit-Bridge, TSE-Ausfallbehandlung und ZVT-Anbindung sind vorbereitet. Der vollständige DSFinV-K-Export und die Realhardware-Abnahme sind noch nicht freigegeben; TOR POS bleibt deshalb im TESTBETRIEB."] =
            "The Swissbit bridge, TSE failure handling and the ZVT connection are prepared. The full DSFinV-K export and the real-hardware acceptance are not released yet, so TOR POS stays in TEST MODE.",
        ["Kasse · Technische Feinabstimmung"] = "Till · technical fine tuning",
        ["Diese Werte werden bei Installation gesetzt und gehören nicht in den täglichen Betrieb."] =
            "These values are set during installation and do not belong in daily operation.",
        ["Kassenidentität & Darstellung"] = "Till identity & appearance",
        ["Kassennummer"] = "Till number",
