        ["BAR-ANTEIL EINGEBEN"] = "ENTER THE CASH SHARE",
        ["Der Kunde gibt Leergut zurück. Der Pfandbetrag wird abgezogen; ist er höher als der Einkauf, wird die Differenz bar ausgezahlt. Menge vorher über die Zifferntasten eingeben."] =
            "The customer is returning empties. The deposit is deducted; if it is higher than the purchase, the difference is paid out in cash. Enter the quantity on the number keys first.",
        ["Name, z.B. Klein 26 cm"] = "Name, e.g. small 26 cm",
        ["KARTENZAHLUNG · TEST"] = "CARD PAYMENT · TEST",
        ["Testsimulation – keine echte Terminalbuchung. "] = "A test simulation – not a real terminal booking. ",
        ["TOR-Regel: Offene geparkte Bons sperren den Z-Abschluss."] =
            "TOR rule: open parked receipts block the Z-Abschluss.",
        ["Bonnummer (optional)"] = "Receipt number (optional)",
        ["ARCHIV · Ältere Bons können angesehen oder als Kopie gedruckt werden. STORNO / TEILRETOURE ist ausschließlich am Verkaufstag möglich."] =
            "ARCHIVE · older receipts can be viewed or printed as a copy. A VOID or PARTIAL RETURN is only possible on the day of sale.",
        ["Von: "] = "From: ",
        [" Bis: "] = " To: ",
        ["TEILRETOURE"] = "PARTIAL RETURN",
        ["Menge je Position eingeben, die zurückgenommen werden soll. Bereits zurückgenommene Mengen werden serverseitig erneut geprüft."] =
            "Enter the quantity to take back for each line. Quantities already returned are checked again on the server.",
        ["Bemerkung (optional), z. B. Zählfehler Wechselgeld"] =
            "Note (optional), e.g. a counting error in the change",
        ["Kommerzielle Lizenz deaktivieren"] = "Deactivate the commercial licence",
