        ["INVENTUR / WARENBESTAND"] = "INVENTORY / STOCK",
        ["Gesamte aktive Artikelliste · Scanner-EAN lesen → Bestand eingeben → ENTER. Mindestbestand, EK/VK und Warenwert sind direkt sichtbar."] =
            "The whole active product list · scan an EAN → enter the stock → ENTER. The minimum level, the purchase and sale price and the stock value are visible directly.",
        ["Z-ABSCHLUSS-JOURNAL"] = "Z-ABSCHLUSS JOURNAL",
        ["PFAND / LEERGUT"] = "DEPOSIT / EMPTIES",
        ["Direkte Pfand-/Leergut-Tasten der Einzelhandel-Version. Werte in Cent."] =
            "The direct deposit and empties keys of the retail version. The values are in cents.",
        ["Bericht als PDF speichern"] = "Save the report as a PDF",
