        // Einrichtung, Diagnose, Zahlungsprüfung, Belegwahl, Bestellübersicht und Demo
        ["VERBINDUNG TESTEN"] = "TEST THE CONNECTION",
        ["ZVT ANMELDUNG TESTEN"] = "TEST THE ZVT LOGIN",
        ["TERMINAL-TAGESABSCHLUSS"] = "TERMINAL END OF DAY",
        ["BONLOGO AUSWÄHLEN"] = "CHOOSE A RECEIPT LOGO",
