        ["STATUS AKTUALISIEREN"] = "REFRESH THE STATUS",
        ["ÖFFNEN"] = "OPEN",
        ["JA, TRENNEN"] = "YES, DISCONNECT",
        ["DATEV-Status wird geladen …"] = "Loading the DATEV status …",
        ["Kein Logo ausgewählt"] = "No logo chosen",
        ["Einmal auswählen, speichern – TOR setzt das Logo danach automatisch oben auf den Bon."] =
            "Choose it once and save – TOR then puts the logo at the top of the receipt automatically.",
        ["Kassenmeldung automatisch jede Minute. TOR POS gleicht Artikel/Bestand nach Verkauf, Artikelpflege und Inventur automatisch im Hintergrund ab; zusätzlich erfolgt beim Start und stündlich ein Reparatur-Snapshot. "] =
            "The till reports automatically every minute. TOR POS reconciles products and stock in the background after a sale, product maintenance and inventory; in addition a repair snapshot is taken at start and every hour. ",
        ["Berichte werden als PDF geöffnet; den A4-Drucker im PDF-Druckdialog auswählen."] =
            "Reports open as a PDF; choose the A4 printer in the PDF print dialog.",
        ["FISKALSTATUS FEHLER"] = "FISCAL STATUS ERROR",
        ["Gespeichertes App-Passwort vorhanden · leer lassen zum Behalten"] =
            "An app password is stored · leave it empty to keep it",
        ["Gespeichertes Passwort nicht lesbar · neu eingeben"] =
