        ["Offizielle Swissbit WormAPI.dll auswählen"] = "Choose the official Swissbit WormAPI.dll",
        ["Zielordner für DSFinV-K Export auswählen"] = "Choose a target folder for the DSFinV-K export",
        ["Signierte TOR-POS-Lizenz auswählen"] = "Choose the signed TOR POS licence",
        ["Techniker-Zugang"] = "Technician access",
        ["Techniker-Passwort einrichten"] = "Set up a technician password",
        ["ALLE GERÄTE PRÜFEN"] = "CHECK ALL DEVICES",
        ["PERFORMANCE AKTUALISIEREN"] = "REFRESH THE PERFORMANCE",
        ["MESSWERTE ZURÜCKSETZEN"] = "RESET THE MEASUREMENTS",
        ["LOG-ORDNER ÖFFNEN"] = "OPEN THE LOG FOLDER",
