        ["ALS GEKLÄRT MARKIEREN"] = "MARK AS CLARIFIED",
        ["ERNEUT DRUCKEN"] = "PRINT AGAIN",
        ["Noch nicht geprüft."] = "Not checked yet.",
        ["SYSTEMSTATUS / DIAGNOSE"] = "SYSTEM STATUS / DIAGNOSIS",
        ["Geräte werden nur auf Anforderung geprüft. Jeder externe Test ist zeitlich begrenzt und darf die Kassenoberfläche nicht lange blockieren."] =
            "Devices are only checked on request. Every external test is time limited and may not block the till screen for long.",
        ["z. B. 20260914-153000-AB12"] = "e.g. 20260914-153000-AB12",
        ["Fehler-ID eingeben, die einem Kassierer/Kunden angezeigt wurde."] =
            "Enter the error ID that was shown to a cashier or customer.",
        ["Noch nicht vorbereitet. Dieser Bereich startet keine TSE-Transaktion."] =
            "Not prepared yet. This area starts no TSE transaction.",
        ["Konnte nicht geladen werden: "] = "Could not be loaded: ",
        ["Keine blockierten Kartenerstattungen."] = "There are no blocked card refunds.",
        ["Bearbeiter"] = "Handled by",
        ["Ergebnis der Prüfung (z. B. 'Terminal/Bank bestätigt: keine Belastung')"] =
            "The result of the check (e.g. 'terminal/bank confirmed: no charge')",
        ["Keine blockierten Küchenbons."] = "There are no blocked kitchen tickets.",
        ["Noch keine Messungen."] = "No measurements yet.",
        ["TOR POS · Systemstatus / Diagnose"] = "TOR POS · system status / diagnosis",
        ["Zahlung bestätigt / Buchung abschließen"] = "Payment confirmed / complete the booking",
        ["Keine Belastung nachweislich bestätigt"] = "No charge was demonstrably confirmed",
        ["Später prüfen · gesperrt lassen"] = "Check later · leave it locked",
        ["Zugang sicher speichern"] = "Store the access securely",
        ["Administrator"] = "Administrator",
        ["Admin-Passwort"] = "Admin password",
        ["Terminalbeleg / Trace / Prüfnachweis und Begründung"] = "Terminal receipt / trace / evidence and reason",
        ["Zuerst Terminal / Netzbetreiber prüfen. Diese Auswahl sendet weder Zahlung noch Storno an das Terminal."] =
            "Check the terminal and the network operator first. This choice sends neither a payment nor a void to the terminal.",
        ["Aktuelles Passwort"] = "Current password",
        ["Neues Passwort (mindestens 4 Zeichen)"] = "New password (at least 4 characters)",
        ["Neues Passwort wiederholen"] = "Repeat the new password",
        ["Neue PIN (4 Ziffern)"] = "New PIN (4 digits)",
        ["Vor dem ersten Kassenstart müssen Standard-Zugangsdaten geändert werden."] =
            "The default credentials have to be changed before the till is first used.",
        ["ZAHLUNG PRÜFEN"] = "CHECK THE PAYMENT",
        ["ADMIN-ZUGANG EINRICHTEN"] = "SET UP THE ADMIN ACCESS",
        ["1 · GERÄTELISTE LADEN"] = "1 · LOAD THE DEVICE LIST",
        ["2 · GERÄTESTATUS PRÜFEN"] = "2 · CHECK THE DEVICE STATUS",
        ["3 · 1,00 € TEST AN SOLO SENDEN"] = "3 · SEND A €1.00 TEST TO THE SOLO",
        ["4 · TEST ABBRECHEN"] = "4 · CANCEL THE TEST",
        ["SOLO MIT DIESEM KONTO KOPPELN"] = "PAIR THE SOLO WITH THIS ACCOUNT",
        ["Händlercode (Merchant Code)"] = "Merchant code",
        ["SumUp API-Key"] = "SumUp API key",
        ["Werbung im Leerlauf anzeigen"] = "Show advertising while idle",
        ["Werbeinhalt"] = "Advertising content",
        ["BEIDE = eigene Werbebilder und Artikel mit Bild · BILDER = nur eigene Werbebilder · ARTIKEL = Artikel mit Bild, Preis und aktivem Angebot."] = "BEIDE = own advertising pictures and products with a picture · BILDER = own advertising pictures only · ARTIKEL = products with picture, price and active offer.",
        ["Wechsel alle (Sek.)"] = "Change every (sec.)",
        ["Sobald ein Artikel gescannt wird, zeigt das Kundendisplay sofort den Warenkorb."] = "As soon as an item is scanned, the customer display shows the cart immediately.",
        ["WERBEBILDER HINZUFÜGEN"] = "ADD ADVERTISING PICTURES",
        ["WERBEBILDER-ORDNER ÖFFNEN"] = "OPEN ADVERTISING FOLDER",
        ["Werbung im Leerlauf"] = "Advertising while idle",
        ["Ohne Kunden wechselt das Kundendisplay zwischen den eigenen Werbebildern (JPG, PNG, BMP, WEBP; Reihenfolge nach Dateiname) und Artikeln mit Bild. Artikelkarten zeigen den aktuellen Verkaufspreis und ein aktives Angebot genau so, wie die Kasse sie berechnet. Kein Einfluss auf Bon, TSE oder Kassiervorgang."] = "Without customers, the customer display rotates your own advertising pictures (JPG, PNG, BMP, WEBP; ordered by file name) and products with a picture. Product cards show the current price and an active offer exactly as the till calculates them. No effect on receipt, TSE or checkout.",
        ["Nicht übernommen"] = "Not added",
        ["Werbebilder konnten nicht übernommen werden"] = "Advertising pictures could not be added",
        ["Ordner konnte nicht geöffnet werden"] = "Folder could not be opened",
        ["Noch keine eigenen Werbebilder. Artikel mit Bild werden trotzdem gezeigt, wenn der Inhalt BEIDE oder ARTIKEL ist."] = "No own advertising pictures yet. Products with a picture are still shown when the content is BEIDE or ARTIKEL.",
        ["eigene Werbebilder"] = "own advertising pictures",
        ["Werbebilder gespeichert"] = "Advertising pictures saved",
        ["Werbebilder-Ordner konnte nicht gelesen werden"] = "Advertising folder could not be read",
        ["Werbe-TV im Netzwerk verwenden"] = "Use advertising TV on the network",
        ["Werbe-TV · Smart-TV im WLAN"] = "Advertising TV · Smart TV on Wi-Fi",
        ["Der TV prüft jede Minute, ob sich Bilder oder Preise geändert haben."] = "The TV checks every minute whether pictures or prices have changed.",
        ["TV-Port"] = "TV port",
        ["Nur ändern, wenn ein anderes Programm diesen Port belegt."] = "Change only if another program uses this port.",
        ["NEUE TV-ADRESSE ERZEUGEN"] = "CREATE NEW TV ADDRESS",
        ["So kommt die Werbung auf den TV"] = "How the advertising gets onto the TV",
        ["Kasse und TV im selben WLAN/Netzwerk. Am TV den Internet-Browser öffnen (Samsung: Internet, LG: Webbrowser, Android TV: z. B. ein Kiosk-Browser) und die Adresse oben eingeben. Die Werbebilder sind dieselben wie beim Kundendisplay; Inhalt und Wechselzeit werden hier getrennt eingestellt. Beim ersten Start fragt Windows eventuell nach der Firewall: Zugriff in privaten Netzwerken erlauben. Die Seite ist nur im eigenen Netzwerk erreichbar und hat keinen Einfluss auf Bon, TSE oder Kassiervorgang."] = "Till and TV on the same Wi-Fi/network. Open the internet browser on the TV (Samsung: Internet, LG: Web Browser, Android TV: e.g. a kiosk browser) and enter the address above. The advertising pictures are the same as for the customer display; content and interval are set separately here. On first start Windows may ask about the firewall: allow access on private networks. The page can only be reached from your own network and has no effect on receipts, TSE or checkout.",
        ["Neue TV-Adresse erzeugt - am TV neu eingeben"] = "New TV address created - enter it again on the TV",
        ["TV-Adresse konnte nicht ermittelt werden"] = "TV address could not be determined",
        ["Die TV-Adresse erscheint nach dem Einschalten und Speichern."] = "The TV address appears after switching on and saving.",
        ["Kein lokales Netzwerk gefunden. Kasse mit dem WLAN/LAN des TVs verbinden."] = "No local network found. Connect the till to the TV's Wi-Fi/LAN.",
        ["Am TV im Browser eingeben"] = "Enter in the TV's browser",
        ["WERBE-TV: Der gewählte TV-Port ist belegt oder gesperrt. In Einstellungen einen anderen TV-Port wählen."] = "ADVERTISING TV: The selected TV port is in use or blocked. Choose another TV port in Settings.",
        ["KASSENABSCHLUSS NACH UPDATE NÖTIG"] = "CLOSING REQUIRED AFTER UPDATE",
        ["TOR POS wurde aktualisiert, aber der automatische Kassenabschluss war nicht möglich, weil noch geparkte Bons oder ein offener Vorgang vorhanden waren. Bitte offene Bons kassieren und heute einen Z-Abschluss durchführen."] = "TOR POS was updated, but the automatic closing was not possible because parked receipts or an open transaction remained. Please settle open receipts and run a Z-Abschluss today.",
        ["Kopplungscode vom Solo (nur bei neuer Kopplung)"] = "Pairing code from the Solo (only for a new pairing)",
        ["Geräteliste laden, danach Solo auswählen"] = "Load the device list, then choose the Solo",
        ["Verbindungstest. Der 1,00-€-Test sendet eine ECHTE Zahlungsanforderung an das Solo. KEINE KARTE vorhalten; danach ABBRECHEN."] =
            "A connection test. The €1.00 test sends a REAL payment request to the Solo. DO NOT present a card; cancel afterwards.",
        ["WICHTIG: 1,00 € SENDEN dient nur dazu zu prüfen, ob der Betrag auf dem Solo erscheint. Wenn eine Karte vorgehalten wird, kann eine echte Zahlung entstehen. Sobald 1,00 € am Solo sichtbar ist, TEST ABBRECHEN drücken oder direkt am Solo abbrechen."] =
            "IMPORTANT: SEND €1.00 only checks whether the amount appears on the Solo. If a card is presented, a real payment can happen. As soon as €1.00 is visible on the Solo, press CANCEL TEST or cancel on the Solo itself.",
        ["Neues Gerät: Solo abmelden → Verbindungen / Connections → API → Verbinden / Connect. Code innerhalb von 5 Minuten verwenden."] =
            "A new device: sign out on the Solo → Connections → API → Connect. Use the code within 5 minutes.",
        ["SUMUP SOLO · VERBINDUNG + 1,00 € TEST"] = "SUMUP SOLO · CONNECTION + €1.00 TEST",
        ["KARTE TEST im normalen Kassenbild bleibt Simulation. Dieser separate Admin-Test sendet nur eine feste 1,00-€-Anforderung an das ausgewählte Solo; Zugangsdaten werden nicht gespeichert."] =
            "CARD TEST on the normal till screen stays a simulation. This separate admin test only sends a fixed €1.00 request to the chosen Solo; the credentials are not stored.",
        ["SumUp Solo · Verbindung + 1,00 € Gerätetest"] = "SumUp Solo · connection + €1.00 device test",
        ["ALLE BENUTZER SPEICHERN"] = "SAVE ALL USERS",
        ["ADMIN-ZUGANG ÄNDERN"] = "CHANGE THE ADMIN ACCESS",
        ["Benutzer aktiv"] = "User active",
        ["MITARBEITER & RECHTE"] = "STAFF & PERMISSIONS",
        ["Neben dem Admin stehen genau drei Mitarbeiterkonten bereit. "] =
            "Besides the admin there are exactly three staff accounts. ",
        ["ADMIN-ZUGANG"] = "ADMIN ACCESS",
        ["Standard bei einer neuen Installation: Benutzer admin · Passwort admin · PIN 1234. "] =
            "Default on a new installation: user admin · password admin · PIN 1234. ",
        ["Aktuelles Admin-Passwort"] = "Current admin password",
        ["Neues Admin-Passwort"] = "New admin password",
        ["Neue 4-stellige Admin-PIN"] = "New 4-digit admin PIN",
        ["Berechtigungen"] = "Permissions",
        ["Einstellungen und Benutzerverwaltung bleiben immer ausschließlich beim Admin."] =
            "The settings and user management always stay with the admin alone.",
        ["TOR POS – Mitarbeiter & Rechte"] = "TOR POS – staff & permissions",
        ["Automatische Kartenterminal-Anbindung aktivieren"] = "Switch on the automatic card terminal connection",
        ["PROFIL SPEICHERN"] = "SAVE THE PROFILE",
        ["SUMUP GERÄT / PAIRING ÖFFNEN"] = "OPEN THE SUMUP DEVICE / PAIRING",
        ["Modell / eigene Notiz (optional)"] = "Model / your own note (optional)",
        ["z. B. 192.168.1.50"] = "e.g. 192.168.1.50",
        ["IP und Port stehen je nach Anbieter im Terminalmenü. Häufig ist der ZVT-Port 20007; maßgeblich ist immer die tatsächliche Terminalkonfiguration."] =
            "The IP and port are in the terminal menu, depending on the provider. The ZVT port is often 20007; what counts is always the actual terminal configuration.",
        ["KARTENTERMINAL VERBINDEN"] = "CONNECT THE CARD TERMINAL",
        ["Marke bzw. Terminalfamilie auswählen. TOR zeigt nur die Angaben, die für diesen Integrationsweg benötigt werden. Ein gelisteter Hersteller bedeutet nicht automatisch, dass dessen proprietäre Schnittstelle ohne Providerfreigabe verwendet werden darf."] =
            "Choose the brand or terminal family. TOR only shows the details needed for that integration route. A listed manufacturer does not automatically mean its proprietary interface may be used without a provider release.",
        ["Sicherheitsregel: TOR POS speichert keine vollständige Kartennummer, keine PIN und keinen CVV/CVC. Nicht freigegebene Providerprofile bleiben automatisch deaktiviert; TOR startet darüber keine vermeintliche Zahlung."] =
            "Safety rule: TOR POS stores no full card number, no PIN and no CVV/CVC. Provider profiles that are not released stay switched off automatically; TOR starts no supposed payment through them.",
        ["TOR POS · Kartenterminal-Assistent"] = "TOR POS · card terminal assistant",
        ["Manuelle Gewichtseingabe immer erlauben"] = "Always allow manual weight entry",
        ["KONFIGURATION PRÜFEN"] = "CHECK THE CONFIGURATION",
        ["WAAGEN-EINSTELLUNGEN SPEICHERN"] = "SAVE THE SCALE SETTINGS",
        ["z. B. Bizerba, Mettler Toledo, CAS"] = "e.g. Bizerba, Mettler Toledo, CAS",
        ["Modellbezeichnung"] = "Model name",
        ["z. B. COM3"] = "e.g. COM3",
        ["z. B. 192.168.1.60"] = "e.g. 192.168.1.60",
        ["z. B. 21"] = "e.g. 21",
        ["WAAGE / GEWICHTSVERKAUF"] = "SCALE / SALE BY WEIGHT",
        ["Manueller Gewichtsverkauf funktioniert immer ohne Kassenanschluss: Gewicht an einer separaten Waage ablesen und beim Artikel in g oder kg eingeben. Diese Einstellungen bereiten zusätzlich angeschlossene Waagen bzw. Waagen-Barcodes vor."] =
            "Selling by weight manually always works without a connection to the till: read the weight on a separate scale and enter it on the product in g or kg. These settings additionally prepare connected scales or scale barcodes.",
        ["Hinweis: SERIELL/LAN speichert die Geräteparameter, aktiviert aber ohne freigegebenes Herstellerprotokoll keinen automatischen Gewichtsempfang. TOR gibt deshalb keinen erfolgreichen Gerätetest vor, wenn nur IP/COM konfiguriert ist."] =
            "Note: SERIAL/LAN stores the device parameters but does not switch on automatic weight reception without a released manufacturer protocol. TOR therefore does not pretend a device test succeeded when only IP or COM is configured.",
        ["TOR POS · Waagen-Einstellungen"] = "TOR POS · scale settings",
        ["ZURÜCK"] = "BACK",
        ["WEITER"] = "NEXT",
        ["Bondrucker verwenden"] = "Use a receipt printer",
        ["Automatische Kartenterminal-Anbindung verwenden"] = "Use the automatic card terminal connection",
        ["Firma & Kassenart"] = "Company & till type",
        ["Kontrolle"] = "Check",
        ["Fertig"] = "Done",
        ["✓ Testbon gesendet."] = "✓ The test receipt was sent.",
        ["TOR POS – Ersteinrichtung"] = "TOR POS – first-time setup",
        ["PAPIERBELEG"] = "PAPER RECEIPT",
        ["DIGITALBELEG (QR)"] = "DIGITAL RECEIPT (QR)",
        ["Wie möchte der Kunde den Beleg erhalten?"] = "How would the customer like to receive the receipt?",
        ["Digitalbeleg: Der Kunde scannt den QR-Code und öffnet den Bon im Browser - lesen, als PDF herunterladen, teilen oder drucken. Nur mit seiner Zustimmung."] =
            "Digital receipt: the customer scans the QR code and opens the receipt in the browser - read it, download it as a PDF, share it or print it. Only with their consent.",
        ["DIGITALER KASSENBON"] = "DIGITAL RECEIPT",
        ["Wird bei TOR Cloud erstellt …"] = "Being created in the TOR Cloud …",
        ["IHR DIGITALER KASSENBON"] = "YOUR DIGITAL RECEIPT",
        ["DIGITALBELEG NICHT MÖGLICH"] = "A DIGITAL RECEIPT IS NOT POSSIBLE",
        ["Beleg"] = "Receipt",
        ["Digitaler Kassenbon"] = "Digital receipt",
        ["z. B. steuerberater@kanzlei.de"] = "e.g. taxadviser@firm.de",
        ["DSFINV-K EXPORT IST FERTIG"] = "THE DSFINV-K EXPORT IS READY",
        ["Wie möchten Sie die Prüfungsdaten weitergeben? Der bereits erzeugte Original-Export bleibt unverändert erhalten."] =
            "How would you like to pass the audit data on? The original export that was already created stays unchanged.",
        ["TOR kopiert den vollständigen DSFinV-K-Ordner mit allen CSV-, XML-, DTD- und Protokolldateien. Es wird nicht nur eine einzelne CSV kopiert."] =
            "TOR copies the whole DSFinV-K folder with all CSV, XML, DTD and log files. It does not copy just a single CSV.",
        ["Für E-Mail packt TOR den vollständigen Export in eine ZIP-Datei und verwendet den unter Berichte & E-Mail aktiven Versandweg (TOR Mail, Google oder SMTP). Die Empfänger-Adresse kann für diesen Versand frei geändert werden."] =
            "For e-mail TOR packs the whole export into a ZIP file and uses the delivery route active under Reports & e-mail (TOR Mail, Google or SMTP). The recipient address can be changed freely for this delivery.",
        ["E-Mail-Hinweis: Große Prüfdatensätze können Mail-Größenlimits überschreiten. TOR versendet deshalb keine ZIP-Datei über 15 MB; in diesem Fall USB/Datenträger verwenden."] =
            "E-mail note: large audit data sets can exceed mail size limits. TOR therefore sends no ZIP file above 15 MB; use USB or another medium in that case.",
        ["TOR POS · DSFinV-K weitergeben"] = "TOR POS · passing DSFinV-K on",
        ["USB-Laufwerk oder Zielordner auswählen"] = "Choose a USB drive or a target folder",
        ["LINK AUF DIESEM PC ÖFFNEN"] = "OPEN THE LINK ON THIS PC",
        ["Warte auf Google-Anmeldung …"] = "Waiting for the Google sign-in …",
        ["MIT GOOGLE ANMELDEN"] = "SIGN IN WITH GOOGLE",
        ["QR-Code mit dem Handy scannen. Google-Passwort und 2-Faktor-Code werden ausschließlich bei Google eingegeben – niemals in TOR POS."] =
            "Scan the QR code with the phone. The Google password and the two-factor code are entered at Google only – never in TOR POS.",
        ["TOR POS fordert nur die Berechtigung „E-Mails senden“ (gmail.send). Der QR-Code ist einmalig und läuft nach wenigen Minuten ab."] =
            "TOR POS only asks for the \"send e-mail\" permission (gmail.send). The QR code is single use and expires after a few minutes.",
        ["TOR POS · Mit Google anmelden"] = "TOR POS · sign in with Google",
        ["Bei Barzahlung automatisch öffnen"] = "Open automatically on a cash payment",
        ["Drucker automatisch suchen"] = "Search for printers automatically",
        ["DRUCKER-ZENTRALE"] = "PRINTER CENTRE",
        ["TOR liest Windows-Druckername, Treiber und Port. Epson- und Star-Bondrucker werden nur dann mit einem konkreten Modell bezeichnet, wenn der Modellname eindeutig erkannt wird. Bei unklarem Modell bleibt die Auswahl bewusst manuell."] =
            "TOR reads the Windows printer name, the driver and the port. Epson and Star receipt printers are only named with a concrete model when the model name is recognised for certain. If the model is unclear, the choice is deliberately left manual.",
        ["Kassenschubladen-Test: TOR verwendet je nach Drucker das passende Protokoll: Epson ESC/POS oder Star StarPRNT. Falls Ausgang 1 nicht öffnet, Ausgang 2 wählen und erneut testen. Der Test erzeugt keinen Verkauf und keinen Bon; die mechanische Öffnung muss am Gerät kontrolliert werden."] =
            "Cash drawer test: TOR uses the protocol that fits the printer, Epson ESC/POS or Star StarPRNT. If output 1 does not open, choose output 2 and test again. The test creates no sale and no receipt; the mechanical opening has to be checked at the device.",
